F(kh),\qquad 
F(kh)=\frac{k h}{\cosh kh+kh\sinh kh}
      =\frac{1}{\,\dfrac{\cosh kh}{k h}+\sinh kh\,} ,
\end{equation*}

so that with the convention $e_{s}= \chi S_{0}/\Delta\rho g$

\begin{equation*}
\chi(kh)=\frac{k h}{\cosh kh+kh\sinh kh}
       =\frac{1}{\dfrac{\cosh kh}{k h}+\sinh kh} ,
\end{equation*}
is the (viscosity independent) steady topographic response.  In
particular

\begin{equation*}
\chi(kh)\xrightarrow[kh\ll1]{}kh-\tfrac32(kh)^{3}+O\big((kh)^{5}\big),\qquad
\chi(kh)\xrightarrow[kh\gg1]{}2\,e^{-kh}\bigl[1+O((kh)^{-1})\bigr],
\end{equation*}
