\begin{equation*}
F''+k^{2}F=2k\Big[-k^{2}cz\cosh kz+d\cosh kz+dkz\sinh kz\Big],
\end{equation*}
so that at $z=h$

\begin{equation*}
\big[F''+k^{2}F\big]_{h}
=-\frac{2kc}{h\cosh\alpha}\Big[\alpha^{2}+\cosh^{2}\alpha\Big] .
\end{equation*}
Hence with $\sigma_{xz}(h)=S_{0}\sin kx$

\begin{equation*}
S_{0}= \mu\big[F''+k^{2}F\big]_{h}
     =-\frac{2\mu kc}{h\cosh\alpha}\Big[\alpha^{2}+\cosh^{2}\alpha\Big] .
\end{equation*}
Eliminating $c$ with $c=-\rho ge/2\mu k^{2}$,

\begin{equation*}
S_{0}= \rho g e\,
\frac{\alpha^{2}+\cosh^{2}\alpha}{\alpha\cosh\alpha},
\qquad\alpha=kh,
\end{equation*}
i.e. in the steady $\dot e=0$ limit, up to the $180^{\circ}$
$\sin kx\leftrightarrow\cos kx$ sign,

\begin{equation*}
e_{s}= \frac{S_{0}}{\rho g}\,
\frac{\alpha\cosh\alpha}{\alpha^{2}+\cosh^{2}\alpha}
     =\frac{S_{0}}{\rho g}
\Bigg[\frac{\alpha}{\cosh\alpha}
      +\frac{\cosh\alpha}{\alpha}\Bigg]^{-1},
\qquad\alpha=kh,
\end{equation*}
the viscosity having cancelled out of the steady amplitude.  Writing
the isostatic restoring traction in the conventional form
$\sigma_{zz}(0)=\Delta\rho g e\cos kx$,

\begin{equation*}
e_{s}= \chi(\alpha)\frac{S_{0}}{\Delta\rho g},
\qquad 
